<?php

function modPow($base, $exp, $mod) {
    $result = 1;
    $base = $base % $mod;
    while ($exp > 0) {
        if ($exp % 2 == 1) {
            $result = ($result * $base) % $mod;
        }
        $exp = intdiv($exp, 2);
        $base = ($base * $base) % $mod;
    }
    return $result;
}

function matMul($A, $B, $mod) {
    $n = count($A);
    $C = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) {
        for ($k = 0; $k < $n; $k++) {
            if ($A[$i][$k] == 0) continue;
            for ($j = 0; $j < $n; $j++) {
                $C[$i][$j] = ($C[$i][$j] + $A[$i][$k] * $B[$k][$j]) % $mod;
            }
        }
    }
    return $C;
}

function matPow($M, $p, $mod) {
    $n = count($M);
    $result = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) {
        $result[$i][$i] = 1;
    }
    while ($p > 0) {
        if ($p % 2 == 1) {
            $result = matMul($result, $M, $mod);
        }
        $M = matMul($M, $M, $mod);
        $p = intdiv($p, 2);
    }
    return $result;
}

